import{_ as o,o as a,c as r,ag as l}from"./chunks/framework.OsDJF_Ea.js";const S=JSON.parse('{"title":"SSO 연동 설정","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/sso.md","filePath":"04-org-admin-guide/sso.md","lastUpdated":1776993543000}'),e={name:"04-org-admin-guide/sso.md"};function i(s,t,d,n,h,u){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="sso-연동-설정" tabindex="-1">SSO 연동 설정 <a class="header-anchor" href="#sso-연동-설정" aria-label="Permalink to &quot;SSO 연동 설정&quot;">​</a></h1><p>외부 서비스(하이웍스 등)와 SSO(Single Sign-On)를 설정하여, 기관 사용자가 Workhub에서 외부 서비스로 로그인 없이 이동할 수 있습니다.</p><h2 id="sso-설정-추가" tabindex="-1">SSO 설정 추가 <a class="header-anchor" href="#sso-설정-추가" aria-label="Permalink to &quot;SSO 설정 추가&quot;">​</a></h2><ol><li>관리자 메뉴 &gt; <strong>SSO 연동 설정</strong>으로 이동합니다.</li><li><strong>&quot;SSO 설정 추가&quot;</strong> 버튼을 클릭합니다.</li><li>다음 정보를 입력합니다:</li></ol><table tabindex="0"><thead><tr><th>항목</th><th>설명</th><th>예시</th></tr></thead><tbody><tr><td>서비스</td><td>SSO 프로바이더 선택</td><td>하이웍스 (Hiworks)</td></tr><tr><td>표시명</td><td>사용자에게 표시되는 이름</td><td>하이웍스</td></tr><tr><td>API Key</td><td>외부 서비스에서 발급받은 API Key</td><td>cf37c94b...</td></tr><tr><td>오피스 도메인</td><td>외부 서비스 오피스 도메인</td><td>dohwa.pro</td></tr><tr><td>오피스 고유번호</td><td>하이웍스 오피스관리 &gt; 회사정보에서 확인</td><td>606410</td></tr><tr><td>공용 로그인 ID</td><td>(선택) 모든 유저가 공유할 하이웍스 아이디</td><td>kjw</td></tr></tbody></table><ol start="4"><li><strong>&quot;등록&quot;</strong> 버튼을 클릭합니다.</li></ol><h2 id="하이웍스-sso-설정-방법" tabindex="-1">하이웍스 SSO 설정 방법 <a class="header-anchor" href="#하이웍스-sso-설정-방법" aria-label="Permalink to &quot;하이웍스 SSO 설정 방법&quot;">​</a></h2><h3 id="사전-준비-하이웍스-관리자-콘솔" tabindex="-1">사전 준비 (하이웍스 관리자 콘솔) <a class="header-anchor" href="#사전-준비-하이웍스-관리자-콘솔" aria-label="Permalink to &quot;사전 준비 (하이웍스 관리자 콘솔)&quot;">​</a></h3><ol><li>하이웍스 오피스관리 &gt; 서비스 연동(API) &gt; <strong>SSO 관리</strong>로 이동합니다.</li><li><strong>내부로 연동</strong> 탭 &gt; **&quot;+ 내부로 연동 추가&quot;**를 클릭합니다.</li><li>API Key를 발급받습니다.</li><li><strong>연동 서버 IP</strong>에 Workhub 서버의 IP 주소를 등록합니다.</li></ol><h3 id="workhub에서-설정" tabindex="-1">Workhub에서 설정 <a class="header-anchor" href="#workhub에서-설정" aria-label="Permalink to &quot;Workhub에서 설정&quot;">​</a></h3><ol><li>발급받은 API Key, 오피스 도메인, 오피스 고유번호를 SSO 설정에 입력합니다.</li><li><strong>연결 테스트</strong> 버튼으로 Temp Key 발급이 정상인지 확인합니다.</li></ol><h2 id="sso-설정-수정" tabindex="-1">SSO 설정 수정 <a class="header-anchor" href="#sso-설정-수정" aria-label="Permalink to &quot;SSO 설정 수정&quot;">​</a></h2><ul><li><strong>수정</strong> 버튼을 클릭하여 설정을 변경할 수 있습니다.</li><li>API Key를 변경하지 않으려면 해당 필드를 <strong>비워두고</strong> 저장하면 기존 키가 유지됩니다.</li><li><strong>활성/비활성</strong> 토글로 SSO를 일시적으로 중단할 수 있습니다.</li></ul><h2 id="sso-사용-일반-사용자" tabindex="-1">SSO 사용 (일반 사용자) <a class="header-anchor" href="#sso-사용-일반-사용자" aria-label="Permalink to &quot;SSO 사용 (일반 사용자)&quot;">​</a></h2><ol><li>사이드바의 외부 서비스 링크를 클릭합니다.</li><li>처음 사용 시 하이웍스 로그인 화면이 표시됩니다.</li><li><strong>하이웍스 아이디</strong>(이메일 앞 아이디 부분만)를 입력하여 계정을 연동합니다.</li><li>이후부터는 자동으로 하이웍스 서비스로 이동합니다.</li></ol><blockquote><p><strong>참고</strong>: 하이웍스 로그인 시 이메일 전체(<a href="mailto:user@domain.com" target="_blank" rel="noreferrer">user@domain.com</a>)가 아닌 <strong>아이디 부분만</strong>(user) 입력해야 합니다.</p></blockquote><h2 id="공용-로그인-계정-운영-선택" tabindex="-1">공용 로그인 계정 운영 (선택) <a class="header-anchor" href="#공용-로그인-계정-운영-선택" aria-label="Permalink to &quot;공용 로그인 계정 운영 (선택)&quot;">​</a></h2><p>기관 내 모든 Workhub 유저가 <strong>하나의 하이웍스 계정</strong>으로 공유 로그인하는 방식을 지원합니다. 외부 유저에게 개별 하이웍스 계정을 발급하기 어려운 경우에 유용합니다.</p><h3 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h3><ol><li>SSO 설정에서 <strong>공용 로그인 ID</strong>에 공유할 하이웍스 아이디 입력 (예: <code>kjw</code>)</li><li>저장 후 모든 Workhub 유저의 SSO 로그인이 이 계정으로 통합됨</li></ol><h3 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h3><ul><li><strong>공용 로그인 ID 미설정</strong>: 유저별로 하이웍스 계정 매핑 (유저가 처음 접속 시 자격증명 입력 필요)</li><li><strong>공용 로그인 ID 설정</strong>: 모든 유저가 동일 계정으로 SSO → 하이웍스 관리자 페이지에 하나의 매핑만 생성됨</li></ul><h3 id="주의사항" tabindex="-1">주의사항 <a class="header-anchor" href="#주의사항" aria-label="Permalink to &quot;주의사항&quot;">​</a></h3><ul><li>공용 계정은 하이웍스 내에서 <strong>활동 이력이 모두 동일 계정으로 기록</strong>됩니다.</li><li>개별 감사(Audit)가 필요한 환경에서는 유저별 매핑 방식 권장.</li></ul>',24)])])}const c=o(e,[["render",i]]);export{S as __pageData,c as default};
